import json
from pathlib import Path
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]
EXPORTS=ROOT/'data'/'exports'
OUT=EXPORTS/'dashboard.html'

def records(name):
    p=EXPORTS/f'{name}.csv'
    return pd.read_csv(p).where(pd.notna(pd.read_csv(p)),None).to_dict(orient='records') if p.exists() else []

def build():
    payload={k:records(k) for k in ('videos','video_metrics','engagement_analysis','channel_summary')}
    data=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YouTube Engagement Analytics</title><style>:root{font-family:Segoe UI,Arial,sans-serif;color:#f6f6f2;background:#10110e;--panel:#1a1c17;--stroke:#30332a;--muted:#a4a899;--lime:#c8f169}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 84% 0%,#34371d 0,transparent 32%),#10110e}header{padding:34px max(5vw,24px) 29px;border-bottom:1px solid var(--stroke);background:linear-gradient(110deg,#181a15,#202116 62%,#302719);position:relative;overflow:hidden}header:after{content:"";position:absolute;width:330px;height:330px;border:1px solid #4a5030;border-radius:50%;right:8%;top:-210px;box-shadow:0 0 0 28px #c8f16908,0 0 0 58px #c8f16908}header h1{margin:10px 0 8px;font-size:clamp(27px,4vw,43px);letter-spacing:-1.6px;max-width:760px}.eyebrow{color:var(--lime);font:500 11px Consolas,monospace;letter-spacing:2px;text-transform:uppercase}.sub{color:#bfc3b2;max-width:650px;font-size:13px;line-height:1.6}.wrap{max-width:1500px;margin:auto;padding:24px max(5vw,24px)}.nav{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:23px;border-bottom:1px solid var(--stroke);padding-bottom:13px}.nav button{background:transparent;color:#aeb2a4;border:1px solid transparent;border-radius:7px;padding:10px 14px;cursor:pointer;font-weight:600;font-size:12px}.nav button.active{color:#10110e;background:var(--lime);font-weight:800}.page{display:none}.page.active{display:block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:12px}.card,.panel{background:linear-gradient(145deg,#1d2019,#171914);border:1px solid var(--stroke);border-radius:13px;padding:18px;margin-bottom:15px;box-shadow:0 9px 30px #0002}.card{min-height:112px;position:relative;overflow:hidden}.card:after{content:"";position:absolute;width:55px;height:55px;border:1px solid #c8f16944;border-radius:50%;right:-25px;bottom:-31px}.label{font:500 10px Consolas,monospace;text-transform:uppercase;letter-spacing:1px;color:#a4a899}.value{font-size:clamp(22px,2.5vw,31px);font-weight:800;margin-top:14px;letter-spacing:-1px;color:#f7f7ec}.cols{display:grid;grid-template-columns:1.4fr 1fr;gap:14px}@media(max-width:800px){.cols{grid-template-columns:1fr}.wrap{padding:18px}}.panel h2,.panel h3{margin:2px 0 14px}.panel h3{font-size:15px}.panel h2{font-size:22px}.muted,small{color:var(--muted);font-size:12px}.panel p{line-height:1.65}.notice{padding:14px;background:#2c281b;border:1px solid #716136;border-radius:9px;color:#e7dba7}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid #2c3027;white-space:nowrap}th{color:var(--lime);font:500 10px Consolas,monospace;text-transform:uppercase;letter-spacing:.7px;position:sticky;top:0;background:#1a1c17}tbody tr:hover{background:#25291e}.barrow{display:grid;grid-template-columns:minmax(125px,2fr) 5fr 80px;gap:10px;align-items:center;margin:13px 0;font-size:11px}.bar{background:#303328;height:10px;border-radius:10px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--lime),#86b84c);border-radius:10px}.barrow b{font:500 10px Consolas,monospace;color:#e1e4d9}.tag{display:inline-block;color:var(--lime);border:1px solid #626b40;border-radius:999px;padding:5px 8px;font:10px Consolas,monospace}.foot{color:#838879;font:10px Consolas,monospace;padding:10px 0 28px}</style></head><body><header><div class="eyebrow">Creator performance / public data</div><h1>YouTube Social Media<br>Engagement Analytics</h1><div class="sub">A snapshot-led look at reach, interaction and publishing patterns for the MrBeast public channel.</div><p><span class="tag">YOUTUBE DATA API V3</span> &nbsp; <span class="tag">LIVE DATASET · 200 VIDEOS</span></p></header><main class="wrap"><div class="nav"><button class="active" data-page="overview">Channel Overview</button><button data-page="videos">Video Performance</button><button data-page="publishing">Publishing Analysis</button><button data-page="insights">Content Insights</button></div>
<section class="page active" id="overview"><div class="grid" id="kpis"></div><div class="cols"><div class="panel"><h3>Top videos by views</h3><div id="topbars"></div></div><div class="panel"><h3>Collection status</h3><div id="status"></div></div></div></section>
<section class="page" id="videos"><div class="panel"><h2>Video Performance</h2><p class="muted">Latest stored observation per video. Rates require available views, likes, and comments.</p><div style="overflow:auto"><table><thead><tr><th>Video</th><th>Published</th><th>Duration (s)</th><th>Views</th><th>Likes</th><th>Comments</th><th>Engagement %</th></tr></thead><tbody id="videorows"></tbody></table></div></div></section>
<section class="page" id="publishing"><div class="panel"><h2>Publishing Analysis</h2><p class="muted">Historical upload-time associations are descriptive and do not prove causation. Reporting timezone: Asia/Kolkata.</p><p id="publishingText"></p><div style="overflow:auto"><table><thead><tr><th>Weekday</th><th>Hour</th><th>Videos</th><th>Median views</th><th>Median engagement %</th></tr></thead><tbody id="patterns"></tbody></table></div></div></section>
<section class="page" id="insights"><div class="panel"><h2>Content Insights</h2><div id="recommendation"></div><p class="notice">Public likes and comments are incomplete interaction measures. Impressions, watch time, audience retention, demographics, and viewer-active times are not available from this public-data workflow.</p><p id="growth"></p></div></section></main><div class="wrap foot">PUBLIC METRICS ONLY · HISTORICAL ASSOCIATIONS ARE NOT CAUSAL · BUILT FROM STORED COLLECTION SNAPSHOTS</div><script>const D=__DATA__;const E=D.engagement_analysis;const V=D.videos;const M=D.video_metrics;const n=x=>Number(x||0);const fmt=x=>x==null?'Unavailable':new Intl.NumberFormat().format(x);const median=a=>{a=a.filter(x=>x!=null).map(Number).sort((x,y)=>x-y);return a.length?(a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2):null};
const latest=new Map(), ratesById=new Map();for(const m of M){const old=latest.get(m.video_id);if(!old||String(m.collected_at)>String(old.collected_at))latest.set(m.video_id,m)}for(const e of E){const old=ratesById.get(e.video_id);if(!old||String(e.collected_at)>String(old.collected_at))ratesById.set(e.video_id,e)}const join=V.map(v=>({...v,...latest.get(v.video_id),...ratesById.get(v.video_id)}));const rates=E.map(x=>x.engagement_rate).filter(x=>x!=null).map(Number);const views=join.map(x=>x.views).filter(x=>x!=null).map(Number);const likes=join.reduce((a,x)=>a+(x.likes==null?0:n(x.likes)),0);const comments=join.reduce((a,x)=>a+(x.comments==null?0:n(x.comments)),0);
const cards=[['Videos analyzed',V.length],['Total latest views',fmt(views.reduce((a,b)=>a+b,0))],['Latest likes available',fmt(likes)],['Latest comments available',fmt(comments)],['Average engagement rate',rates.length?(rates.reduce((a,b)=>a+b,0)/rates.length).toFixed(2)+'%':'Unavailable'],['Median engagement rate',median(rates)==null?'Unavailable':median(rates).toFixed(2)+'%']];document.getElementById('kpis').innerHTML=cards.map(c=>`<div class="card"><div class="label">${c[0]}</div><div class="value">${c[1]}</div></div>`).join('');
const top=[...join].filter(x=>x.views!=null).sort((a,b)=>n(b.views)-n(a.views)).slice(0,10),max=Math.max(1,...top.map(x=>n(x.views)));document.getElementById('topbars').innerHTML=top.map(x=>`<div class="barrow"><span title="${x.title}">${String(x.title||'').slice(0,38)}</span><div class="bar"><i style="width:${100*n(x.views)/max}%"></i></div><b>${fmt(x.views)}</b></div>`).join('')||'<p>No stored observations.</p>';document.getElementById('status').innerHTML=`<p>Stored videos: <b>${V.length}</b></p><p>Metric observations: <b>${M.length}</b></p><p>Engagement observations with all required metrics: <b>${rates.length}</b></p>`;
document.getElementById('videorows').innerHTML=join.sort((a,b)=>n(b.views)-n(a.views)).map(x=>`<tr><td><a style="color:#8fc6ff" href="${x.url}" target="_blank" rel="noreferrer">${x.title}</a></td><td>${String(x.published_at||'').slice(0,10)}</td><td>${fmt(x.duration_seconds)}</td><td>${fmt(x.views)}</td><td>${fmt(x.likes)}</td><td>${fmt(x.comments)}</td><td>${x.engagement_rate==null?'Unavailable':Number(x.engagement_rate).toFixed(2)+'%'}</td></tr>`).join('');
const groups={};for(const x of join){if(!x.published_at)continue;const d=new Date(x.published_at);const k=d.toLocaleString('en-US',{weekday:'long',timeZone:'Asia/Kolkata'})+'|'+Number(new Intl.DateTimeFormat('en-US',{hour:'2-digit',hourCycle:'h23',timeZone:'Asia/Kolkata'}).format(d));(groups[k]??=[]).push(x)}const pats=Object.entries(groups).map(([k,a])=>{const [weekday,hour]=k.split('|');return {weekday,hour,sample:a.length,views:median(a.map(x=>x.views)),rate:median(a.map(x=>x.engagement_rate))}}).sort((a,b)=>a.weekday.localeCompare(b.weekday)||a.hour-b.hour);document.getElementById('patterns').innerHTML=pats.map(x=>`<tr><td>${x.weekday}</td><td>${x.hour}:00</td><td>${x.sample}</td><td>${fmt(x.views)}</td><td>${x.rate==null?'Unavailable':x.rate.toFixed(2)+'%'}</td></tr>`).join('');document.getElementById('publishingText').textContent=pats.length?`${pats.length} weekday/hour groups from available video records.`:'Insufficient publication timestamps.';
document.getElementById('recommendation').innerHTML=rates.length>=5?`<p>Median public engagement is ${median(rates).toFixed(2)}% across ${rates.length} observations with complete metrics.</p><p>Use publishing patterns as descriptive hypotheses only; content, age, and audience factors are not controlled.</p>`:'<p class="notice">Insufficient observations to make a reliable recommendation.</p>';document.getElementById('growth').textContent=M.length>join.length?'Multiple dated snapshots exist. View changes should be interpreted only between actual collection timestamps.':'Only one snapshot per video is available; historical growth cannot yet be calculated.';
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.page).classList.add('active')});</script></body></html>'''.replace('__DATA__',data)
    OUT.write_text(html,encoding='utf-8')
    return OUT
if __name__=='__main__': print(build())

